command:
export SCRATCH="${TMPDIR:-/tmp}/guidebook-t-010"; mkdir -p $SCRATCH && cp data/guidebook.db $SCRATCH/t.db; sha256sum data/guidebook.db | cut -c1-16
TERM=$(python3 -I -c "import sqlite3,os;c=sqlite3.connect('file:'+os.environ['SCRATCH']+'/t.db?mode=ro',uri=True);print(c.execute(\"select t.term_id from terms t where t.domain='functional_axis' and t.term_id not in (select term_id from base_parameters) and t.term_id not in (select term_id from parameter_declinations where revoked_at is null) and t.canonical_en not glob '*[0-9]*' order by t.term_id limit 1\").fetchone()[0])"); echo "probe term: $TERM"; GUIDEBOOK_DB_PATH="$SCRATCH/t.db" python3 scripts/db.py add-parameter --term-id "$TERM" --notes 'TASK-FIXTURE' --session session_task-probe 2>&1 | tail -4; echo rc=${PIPESTATUS[0]}
python3 -I -c "import sqlite3;c=sqlite3.connect('file:data/guidebook.db?mode=ro',uri=True);print(c.execute(\"select domain, count(*) from terms group by 1 order by 2 desc\").fetchall())"; python3 -I -c "import sqlite3;c=sqlite3.connect('file:data/guidebook.db?mode=ro',uri=True);print(c.execute(\"select distinct t.domain from base_parameters p join terms t using(term_id)\").fetchall())"; python3 scripts/db.py amend-term --help | grep -- '--field'

sed -i 's/not in db\.dbcore\.NON_QUANTITY_DOMAINS\]/not in dbcore.NON_QUANTITY_DOMAINS]/' scripts/tests/test_scan_contract.py && export SCRATCH="${TMPDIR:-/tmp}/guidebook-t-010"; cp data/guidebook.db $SCRATCH/t.db
G(){ GUIDEBOOK_DB_PATH="$SCRATCH/t.db" python3 scripts/db.py "$@" 2>&1; }
pick(){ python3 -I -c "import sqlite3,os,sys;c=sqlite3.connect('file:'+os.environ['SCRATCH']+'/t.db?mode=ro',uri=True);print(c.execute(\"select t.term_id from terms t where t.domain=? and t.term_id not in (select term_id from base_parameters) and t.term_id not in (select term_id from parameter_declinations where revoked_at is null) and t.canonical_en not glob '*[0-9]*' order by t.term_id limit 1\",(sys.argv[1],)).fetchone()[0])" "$1"; }
for d in functional_axis legal; do T=$(pick $d); echo "=== $d $T"; G add-parameter --term-id $T --notes TASK-FIXTURE --session session_task-probe | head -8 | cut -c1-260; done
LIVE=$(python3 -I -c "import sqlite3,os;c=sqlite3.connect('file:'+os.environ['SCRATCH']+'/t.db?mode=ro',uri=True);print(c.execute(\"select t.domain from base_parameters p join terms t using(term_id) limit 1\").fetchone()[0])"); T=$(pick $LIVE); echo "=== live domain $LIVE $T"; G add-parameter --term-id $T --notes TASK-FIXTURE --session session_task-probe | grep -E 'parameter_id|REFUS'
echo "=== amend-term domain"; T=$(pick functional_axis); G amend-term --term-id $T --field domain --replacement no_such_domain --reason 'TASK-FIXTURE probe' --session session_task-probe | cut -c1-250; G amend-term --term-id $T --field domain --replacement circulation --reason 'TASK-FIXTURE probe' --session session_task-probe --dry-run | tail -4

grep -n -F "isn't hardcoding necessarily" references/project-standards.md | cut -c1-900; echo ---; git grep -n -E '354|363' -- governance/check-registry.yaml | head; python3 -c "
import yaml
for c in yaml.safe_load(open('governance/check-registry.yaml'))['checks']:
    if c['id'] in ('test_run_pipeline_refusals','test_scan_contract','test_db_amend_writers'): print({k:(str(v)[:160]) for k,v in c.items() if k in ('id','level','cmd','min_items','no_floor','floor','paths','triggers')})
"; sed -n 165,200p workplan/pipeline-state-graph/machines.yaml | cut -c1-200; echo; grep -rn -i -E "terms?\.domain|term domain|domain (vocabulary|values)|functional_axis" sessions references/project-standards.md decisions 2>/dev/null | grep -i -E 'owner|ruling|ruled' | cut -c1-260 | head -12
